 static int books(EnchantRuntime r,ItemStack[] items,String id,int level){int count=0;for(var item:items)if(item!=null&&r.items.book(item).map(b->b.id().equals(id)&&b.level()==level&&b.kind()==EnchantItems.Kind.BOOK).orElse(false))count+=item.getAmount();return count;}
