  String haste="hearth:ce_haste",experience="hearth:ce_experience";var gear=new ItemStack(Material.DIAMOND_PICKAXE);gear.addUnsafeEnchantment(org.bukkit.enchantments.Enchantment.UNBREAKING,3);gear.editMeta(meta->{meta.getPersistentDataContainer().set(new NamespacedKey(plugin,"upgrade"),PersistentDataType.INTEGER,7);meta.lore(List.of(net.kyori.adventure.text.Component.text("외부 장비 설명")));});gear=r.items.write(gear,Map.of(experience,2));byte[] pristine=gear.serializeAsBytes();var inventory=new ItemStack[41];inventory[0]=r.items.book(book(haste,1,1,1,EnchantItems.Kind.BOOK,0));inventory[1]=inventory[0].clone();inventory[2]=gear;inventory[3]=r.items.book(book(haste,1,1,0,EnchantItems.Kind.PROTECTION,0));inventory[4]=r.items.book(book(haste,1,1,0,EnchantItems.Kind.BOOST,1));var limits=r.limits();var random=new Random(13);var plan=r.operations.plan(request(r,EnchantOperations.Action.APPLY,0,2,haste,-1,-1),inventory,r.catalog.snapshot(),rules(1,1,EnchantOperations.Failure.ALL),limits,random);check(plugin,r.items.read(plan.after()[2]).equals(Map.of(haste,1,experience,2))&&Arrays.equals(pristine,gear.serializeAsBytes()),"apply_adds_only_selected_ID_without_mutating_original");check(plugin,plan.after()[2].getEnchantmentLevel(org.bukkit.enchantments.Enchantment.UNBREAKING)==3&&plan.after()[2].getItemMeta().getPersistentDataContainer().get(new NamespacedKey(plugin,"upgrade"),PersistentDataType.INTEGER)==7&&plan.after()[2].getItemMeta().lore().contains(net.kyori.adventure.text.Component.text("외부 장비 설명")),"vanilla_enchant_upgrade_foreign_lore_and_PDC_are_preserved");
