  var bad=inventory.clone();bad[1]=r.items.book(book(haste,2,1,0,EnchantItems.Kind.BOOK,0));boolean reject=false;try{r.operations.plan(request(r,EnchantOperations.Action.FUSE,0,1,haste,-1,-1),bad,r.catalog.snapshot(),rules(1,0,EnchantOperations.Failure.ALL),limits,new Random());}catch(IllegalArgumentException expected){reject=true;}check(plugin,reject,"different_book_levels_are_refused_before_consumption");
